  const RE2 = new RegExp(`(?<![\\w\\[|#])\\*b\\.\\s?(${stems})(?:\\*\\.|\\.\\*)(\\s+)(\\d{1,3})([ab])(?![\\w\\]])`, 'gu');      // *b. Shabb*. 30b, *b. Ber.* 64a
